<?php
$page_title='แชตกับร้านค้า';require_once __DIR__.'/includes/auth_check.php';requireLogin();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$uid=(int)$_SESSION['user_id'];$seller=(int)($_GET['seller']??0);$product=(int)($_GET['product']??0)?:null;$conversation=(int)($_GET['conversation']??0);
if(!$conversation&&$seller){$q=$db->prepare('SELECT id FROM store_conversations WHERE seller_id=? AND customer_id=? AND product_id <=> ?');$q->execute([$seller,$uid,$product]);$conversation=(int)$q->fetchColumn();}
$list=$db->prepare('SELECT sc.*,sp.shop_name,u.username customer_name,p.name product_name FROM store_conversations sc JOIN seller_profiles sp ON sp.user_id=sc.seller_id JOIN users u ON u.id=sc.customer_id LEFT JOIN products p ON p.id=sc.product_id WHERE sc.seller_id=? OR sc.customer_id=? ORDER BY sc.last_message_at DESC');$list->execute([$uid,$uid]);$conversations=$list->fetchAll();$messages=[];$active=null;if($conversation){foreach($conversations as $x)if((int)$x['id']===$conversation)$active=$x;if($active){$q=$db->prepare('SELECT sm.*,u.username FROM store_messages sm JOIN users u ON u.id=sm.sender_id WHERE conversation_id=? ORDER BY id');$q->execute([$conversation]);$messages=$q->fetchAll();$db->prepare('UPDATE store_messages SET is_read=1 WHERE conversation_id=? AND sender_id<>?')->execute([$conversation,$uid]);}}
require_once __DIR__.'/includes/header.php';?><div class="container chat-shell"><aside><h2>ข้อความ</h2><?php foreach($conversations as $x):?><a href="?conversation=<?php echo $x['id'];?>"><strong><?php echo e($uid===$x['seller_id']?$x['customer_name']:$x['shop_name']);?></strong><small><?php echo e($x['product_name']?:'สอบถามร้านค้า');?></small></a><?php endforeach;?></aside><section><div class="chat-messages"><?php if(!$active):?><p>เริ่มพูดคุยกับร้านค้าจากหน้าสินค้า</p><?php endif;?><?php foreach($messages as $x):?><article class="<?php echo $x['sender_id']===$uid?'mine':'';?>"><small><?php echo e($x['username']);?></small><p><?php echo nl2br(e($x['message']));?></p><time><?php echo date('d/m H:i',strtotime($x['created_at']));?></time></article><?php endforeach;?></div><?php if($active||$seller):?><form id="chatForm"><textarea name="message" maxlength="2000" required placeholder="พิมพ์ข้อความ..."></textarea><button class="btn btn-primary">ส่งข้อความ</button></form><?php endif;?></section></div><script nonce="<?php echo e(cspNonce());?>">chatForm?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target);d.append('action','message');d.append('csrf_token',CSRF_TOKEN);d.append('seller_id','<?php echo $active?(int)$active['seller_id']:$seller;?>');d.append('product_id','<?php echo $active?(int)$active['product_id']:(int)$product;?>');d.append('conversation_id','<?php echo $conversation;?>');const r=await fetch(BASE_URL+'api/marketplace.php',{method:'POST',body:d}),j=await r.json();if(j.status==='success')location.href=BASE_URL+'messages.php?conversation='+j.data.conversation_id;else showToast(j.message,'error')});</script><?php require_once __DIR__.'/includes/footer.php';?>
